/* ---------- graf výdajů, kategorie, @přezdívka, vrácení, plánovaná platba ---------- */
const PCATS=['Jídlo','Zábava','Hry','Dárky','Škola','Ostatní'];
const KCAT={out:'Platby',chip:'Kasino',inv:'Burza a krypto',int:'Spoření',loan:'Půjčky'};
const DCOL=['#22d3ee','#a855f7','#f472b6','#facc15','#4ade80','#fb923c','#60a5fa','#94a3b8','#e879f9','#2dd4bf'];
const ICAT=t=>t.t==='Banka'?'Odměny od Banky':t.t==='Dárkový kód'?'Dárkové kódy':({in:'Od lidí',chip:'Kasino',inv:'Burza a krypto',int:'Spoření a úroky',loan:'Půjčky'})[t.k]||'Ostatní';
function incomeHtml(){return spendHtml(true)}
function spendHtml(inc){const m={};S.tx.filter(t=>inc?t.a>0:t.a<0).forEach(t=>{const c=inc?ICAT(t):(t.c||KCAT[t.k]||'Ostatní');m[c]=(m[c]||0)+Math.abs(t.a)});const e=Object.entries(m).sort((a,b)=>b[1]-a[1]),tot=e.reduce((a,b)=>a+b[1],0);
 if(!tot)return `<div class="empty">Zatím žádné ${inc?'příjmy':'výdaje'}.</div>`;let off=0;const R=15.9155;
 return `<div class="donut"><svg viewBox="0 0 42 42"><circle cx="21" cy="21" r="${R}" fill="none" stroke="var(--input)" stroke-width="6"/>${e.map(([c,v],i)=>{const p=v/tot*100,s=`<circle cx="21" cy="21" r="${R}" fill="none" stroke="${DCOL[i%10]}" stroke-width="6" stroke-dasharray="${p} ${100-p}" stroke-dashoffset="${25-off}"/>`;off+=p;return s}).join('')}<text x="21" y="20.5" text-anchor="middle" font-size="4.6" font-weight="700" fill="var(--ink)">${Math.round(tot)}</text><text x="21" y="26" text-anchor="middle" font-size="3" fill="var(--mute)">Sh celkem</text></svg>
<div class="legend">${e.map(([c,v],i)=>`<div><i style="background:${DCOL[i%10]}"></i>${c}<b>${f0(v)}</b></div>`).join('')}</div></div>`}
{const pr=pickRows;pickRows=function(q=''){const t=q.trim();if(t.startsWith('@')){const k=norm(t.slice(1)),o=others().filter(p=>S.nick[p.n]&&norm(S.nick[p.n]).startsWith(k));return o.length?`<div class="pick-h">Přezdívky</div>`+o.map((p,i)=>pickRow(p,i===0)).join(''):`<div class="pick-empty">Nikdo s přezdívkou ${t}.</div>`}return pr(q)}}
{const rw=pickRow;pickRow=function(p,act){return rw(p,act).replace(`<small>${p.r}`,`<small>${S.nick[p.n]?'@'+S.nick[p.n]+' · ':''}${p.r}`)}}
{const pl=P.platby;P.platby=()=>{let h=pl();
 if(S.payTab==='send')h=h.replace('<label class="field">Zpráva pro příjemce',`<div class="cols2"><label class="field">Kategorie<select id="pCat">${PCATS.map(c=>`<option>${c}</option>`).join('')}</select></label><label class="field">Kdy<select id="pWhen"><option value="now">Hned</option><option value="later">Naplánovat</option></select></label></div><label class="field" id="pDateW" style="display:none">Datum platby<input id="pDate" type="date" min="${addDays(1)}" value="${addDays(1)}"></label><label class="field">Zpráva pro příjemce`).replace('placeholder="Jméno nebo číslo účtu"','placeholder="Jméno, @přezdívka nebo číslo účtu"');
 const u=S.undo&&Date.now()<S.undo.until?`<section class="glass box" style="border-color:var(--a2)"><div class="sec"><span><b>Poslal jsi ${fmt(S.undo.a)} → ${S.undo.to}</b><small class="mute" style="display:block">Vrátit jde ještě <span id="undoLeft">${Math.ceil((S.undo.until-Date.now())/60000)}</span> min</small></span><button class="ghost sm" data-act="undo">Vrátit platbu</button></div></section>`:'';
 h=h.replace('<div class="stack">',`<div class="stack">${u}<section class="glass box"><h3>Kam mi tečou peníze</h3>${spendHtml()}</section><section class="glass box"><h3>Odkud mi chodí peníze</h3>${incomeHtml()}</section>`);
 h=h.replace('<h3>Trvalé příkazy</h3>','<h3>Trvalé a plánované platby</h3>').replace('>Provést splatné příkazy (jen prototyp)<','>Provést splatné platby (jen prototyp)<');
 if(S.sched.length)h=h.replace('<h3>Trvalé a plánované platby</h3><button class="ghost sm" data-act="orderNew">+ Nový</button></div>',`<h3>Trvalé a plánované platby</h3><button class="ghost sm" data-act="orderNew">+ Nový</button></div>${S.sched.map((o,i)=>`<div class="tx"><div class="ic">${I('lock')}</div><div class="m"><b>${o.to} · ${fmt(o.a)}</b><small>jednorázově ${cz(o.date)}${o.why?' · '+o.why:''}</small></div><button class="ghost sm" data-act="schedDel" data-v="${i}" aria-label="Zrušit">${I('x')}</button></div>`).join('')}`);
 return h}}
pre('pay',()=>{if($('#pWhen')?.value==='later'){const to=S.pre,a=num('#pAmt'),d=$('#pDate').value;if(!to){toast('Vyber příjemce.',false);return false}if(!(a>0)){toast('Zadej částku.',false);return false}S.sched.push({to,a,date:d,why:$('#pMsg').value.trim()});toast(`Naplánováno: ${fmt(a)} → ${to} na ${cz(d)}`);render(1);return false}});
post('pay',s=>{if(S.tx.length>s.tx){const t=S.tx[0];t.c=$('#pCat')?.value||t.c;const to=t.t.split(' · ')[0];S.undo={a:-t.a,to,until:Date.now()+10*60000,fee:Math.round((-t.a)/(1+S.cfg.fee/100)*S.cfg.fee)/100};S.chats[to]=S.chats[to]||[];render(1)}});
{const orun=A.orderRun;A.orderRun=function(){let n=0;S.sched=S.sched.filter(o=>{const fee=Math.round(o.a*S.cfg.fee)/100;if(o.date<=addDays(400)&&S.bal>=o.a+fee){S.bal-=o.a+fee;fund(fee,'Poplatek z platby');addTx('out',o.to,'plánovaná platba'+(o.why?' · '+o.why:''),-(o.a+fee));n++;return false}return true});if(n)toast(`Provedeno ${n} plánovaných plateb.`);orun()}}

