{const oz=P.oznameni;P.oznameni=()=>{const h=oz(),polls=`<section class="glass box poll"><div class="sec"><h3>Ankety</h3>${['own','bank','dev','vice'].includes(S.role)?'<button class="ghost sm" data-act="pollNew">+ Nová anketa</button>':''}</div>${S.polls.map((p,i)=>{const tot=p.votes.reduce((a,b)=>a+b,0)||1;return `<div style="margin-top:10px"><b>${p.q}</b><small class="mute" style="display:block">${p.by} · ${p.d} · ${tot} hlasů</small>${p.opts.map((o,k)=>`<button class="opt ${p.mine===k?'mine':''}" data-act="vote" data-v="${i}|${k}"><i style="width:${p.votes[k]/tot*100}%"></i><span>${o}${p.mine===k?' ✓':''}<b>${Math.round(p.votes[k]/tot*100)} %</b></span></button>`).join('')}</div>`}).join('')}</section>`;
 return h.replace('<div style="display:flex;flex-direction:column;gap:12px">',polls+'<div style="display:flex;flex-direction:column;gap:12px">')}}

/* ---------- kasino: sázky na školní události, týdenní turnaj ---------- */
function weekEnd(){const d=new Date();d.setDate(d.getDate()+((7-d.getDay())%7));d.setHours(20,0,0,0);if(d<new Date())d.setDate(d.getDate()+7);return d}
{const ks=P.kasino;P.kasino=()=>{const h=ks(),i=h.lastIndexOf('</div>'),admin=['own','bank','dev','vice'].includes(S.role);
 const lb=[['Tomáš',340],['Klára',215],['Ondra',190],['Petr',120],[S.me,S.cas.won]].sort((a,b)=>b[1]-a[1]),left=Math.max(0,Math.round((weekEnd()-new Date())/3600000));
 const tour=`<section class="glass box"><div class="gi">${I('trophy')}</div><h3 style="margin:0">Týdenní turnaj</h3><small class="mute">Kdo vyhraje nejvíc žetonů do neděle 20:00 · konec za ${Math.floor(left/24)} d ${left%24} h</small>${lb.map(([n,v],k)=>`<div class="kv"><span>${k+1}. ${n}${n===S.me?' (ty)':''}</span><b>${v} ž.</b></div>`).join('')}<p class="mute sm" style="margin:10px 0 0">Vítěz dostane 500 Sh z fondu Banky.</p></section>`;
 const bets=`<section class="glass box"><div class="sec"><h3>Sázky na školní události</h3>${admin?'<button class="ghost sm" data-act="betNew">+ Nová</button>':''}</div>${S.bets.map((b,j)=>{const tot=b.pool.reduce((a,c)=>a+c,0);return `<div style="margin-top:12px"><b>${b.q}</b><small class="mute" style="display:block">v banku ${tot} ž. · ${b.open?'sází se':'vyhodnoceno: '+b.opts[b.win]}</small>${b.opts.map((o,k)=>{const odds=b.pool[k]?(tot*.95/b.pool[k]):0;return `<div class="kv"><span>${o}${b.mine[k]?` · <b class="pos">tvoje sázka ${b.mine[k]} ž.</b>`:''}</span><span>${odds?'×'+odds.toFixed(2).replace('.',','):'–'} ${b.open?`<button class="ghost sm" data-act="betOn" data-v="${j}|${k}">Vsadit</button>`:''}${b.open&&admin?` <button class="ghost sm" data-act="betWin" data-v="${j}|${k}" title="Vyhodnotit">✓</button>`:''}</span></div>`}).join('')}</div>`}).join('')}<p class="mute sm" style="margin:10px 0 0">Výhry se dělí podle vsazených žetonů, 5 % jde do Banky.</p></section>`;
 return h.slice(0,i)+bets+tour+h.slice(i)}}

