 const firms=`<section class="glass box"><div class="sec"><h3>Firmy spolužáků</h3><button class="ghost sm" data-act="firmNew">+ Založit firmu</button></div><p class="mute sm">Cena roste, když lidi kupují akcie. Peníze z prodeje dostává majitel firmy.</p><div class="cols3">${S.firms.map(f=>{const p=fprice(f),c=(p/f.h[0]-1)*100;return `<div class="col"><div class="sec"><b>${f.n}</b><small class="mute">${f.id}</small></div><small class="mute">majitel ${f.owner} · prodáno ${Math.round(f.sold/f.shares*100)} %</small>${chart(f.h)}<div class="sec"><b>${fmt(p)}</b><small class="${c>=0?'pos':'neg'}">${pct(c)}</small></div><small class="mute">Máš ${S.fhold[f.id]||0} ks</small>${(f.products||[]).length?`<button class="ghost sm" data-act="shopOpen" data-v="${f.id}">${I('gift')}Obchod · ${f.products.length} produktů</button>`:''}<div class="mini"><button class="cta" style="padding:9px" data-act="fBuy" data-v="${f.id}">Koupit</button><button class="ghost sm" data-act="fSell" data-v="${f.id}">Prodat</button></div></div>`}).join('')}</div></section>`;
