function translate(){if(S.lang!=='en')return;const root=document.body,w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let n;while(n=w.nextNode()){const t=n.nodeValue.trim();if(t&&EN[t])n.nodeValue=n.nodeValue.replace(t,EN[t])}root.querySelectorAll('[placeholder]').forEach(e=>{if(EN[e.placeholder])e.placeholder=EN[e.placeholder]})}
document.documentElement.lang='cs';

/* ---------- akce ---------- */
const download=(name,text,type)=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;document.body.appendChild(a);a.click();a.remove()};
async function sysNotify(title,body){if(!S.phoneNotif||!('Notification' in window)||Notification.permission!=='granted')return;try{const r=await navigator.serviceWorker?.ready;if(r)r.showNotification(title,{body,icon:'ikona.svg',badge:'ikona.svg'});else new Notification(title,{body,icon:'ikona.svg'})}catch(e){}}
{const ic=incoming;incoming=function(from,a,why){ic(from,a,why);sysNotify('NašeBanka',`${from} ti poslal ${fmt(a)}`)}}
const b64=b=>btoa(String.fromCharCode(...new Uint8Array(b))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
const unb64=s=>Uint8Array.from(atob(s.replace(/-/g,'+').replace(/_/g,'/')),c=>c.charCodeAt(0));
try{S.passkey=JSON.parse(localStorage.getItem('nb-passkey')||'null')}catch(e){}
Object.assign(A,{
 econ(b){setEcon(b.dataset.v);toast(b.dataset.v==='normal'?'Ekonomika je zase normální.':'Spuštěno: '+ECON[b.dataset.v][0]);render(1)},
 newsPost(){const id=$('#nwFirm').value,t=$('#nwType').value,ti=$('#nwTitle').value.trim(),tx=$('#nwText').value.trim();if(t==='vlastni'&&!ti)return toast('Napiš nadpis zprávy.',false);postNews(id,t,ti||null,tx||null,S.me);toast('Zpráva zveřejněna.');render(1)},
 newsRandom(){randomEvent();toast('Nová událost v novinách.');render(1)},
 chatOpen(b){S.chatWith=b.dataset.v;S.unreadChat[b.dataset.v]=0;render(1);chatScroll();$('#chatIn')?.focus()},
 chatBack(){S.chatWith=null;render(1)},
 chatNew(){modal('Nová zpráva',`<label class="field">Komu${selPeople('chTo')}</label>`,'Otevřít',()=>{const n=$('#chTo').value;S.chats[n]=S.chats[n]||[];S.chatWith=n;setTimeout(()=>{render(1);$('#chatIn')?.focus()})})},
 chatSend(){const i=$('#chatIn'),t=i.value.trim(),w=S.chatWith;if(!t)return;(S.chats[w]=S.chats[w]||[]).push({f:S.me,t:t.replace(/</g,'&lt;'),d:nowT()});render(1);chatScroll();$('#chatIn').focus();
  setTimeout(()=>{S.chats[w].push({f:w,t:REPL[Math.floor(Math.random()*REPL.length)],d:nowT()});if(route()==='zpravy'&&S.chatWith===w){render(1);chatScroll()}else{S.unreadChat[w]=(S.unreadChat[w]||0)+1;navs();notify(w,`${w}: nová zpráva`,'#/zpravy');sysNotify('NašeBanka',`${w} ti napsal(a) zprávu`)}},1600)},
 undo(){const u=S.undo;if(!u||Date.now()>u.until)return toast('Na vrácení už je pozdě.',false);S.bal+=u.a;fund(-u.fee,'Vrácený poplatek');addTx('in',u.to,'vrácená platba',u.a);S.undo=null;toast('Platba vrácena, peníze jsou zpátky.');render(1)},
 schedDel(b){S.sched.splice(+b.dataset.v,1);toast('Plánovaná platba zrušena.');render(1)},
 redeem(){modal('Dárkový kód','<label class="field">Zadej kód<input id="rdCode" maxlength="20" placeholder="VITEJ2026" style="text-transform:uppercase" autocomplete="off"></label>','Uplatnit',()=>{const k=$('#rdCode').value.trim().toUpperCase(),c=S.codes.find(x=>x.code===k);if(!c){toast('Takový kód neexistuje.',false);return false}if(c.used.includes(S.me)){toast('Tenhle kód už jsi použil.',false);return false}if(c.used.length>=c.max){toast('Kód už je vyčerpaný.',false);return false}c.used.push(S.me);if(c.kind==='Sh'){S.bal+=c.a;fund(-c.a,'Dárkový kód '+k);addTx('in','Dárkový kód',k,c.a)}else{S.chips+=c.a}toast(`Kód uplatněn: +${c.a} ${c.kind}`);setTimeout(()=>render(1))})},
 codeNew(){const k=$('#cdCode').value.trim().toUpperCase(),a=num('#cdAmt'),m=Math.floor(num('#cdMax'));if(!/^[A-Z0-9]{3,20}$/.test(k))return toast('Kód: 3–20 písmen a číslic.',false);if(S.codes.some(c=>c.code===k))return toast('Ten kód už existuje.',false);if(!(a>0)||!(m>0))return toast('Zadej částku a počet použití.',false);S.codes.push({code:k,a,kind:$('#cdKind').value,max:m,used:[]});log('Vytvořil dárkový kód · '+k);toast('Kód '+k+' vytvořen.');render(1)},
 codeDel(b){const c=S.codes.splice(+b.dataset.v,1)[0];log('Smazal dárkový kód · '+c.code);render(1)},
 bulk(){const g=$('#bulkTo').value,a=num('#bulkAmt'),why=$('#bulkWhy').value.trim()||'odměna';if(!(a>0))return toast('Zadej částku.',false);const ppl=visible().filter(p=>g==='all'||(g==='cust'?p.k==='cust':p.k!=='cust')),tot=a*ppl.length;if(tot>S.fund)return toast(`Ve fondu není ${f0(tot)}.`,false);fund(-tot,'Hromadná odměna · '+why,ppl.length+' lidí');if(ppl.some(p=>p.n===S.me)){S.bal+=a;addTx('in','Banka','odměna · '+why,a)}log(`Hromadná odměna · ${ppl.length} × ${fmt(a)}`);toast(`Posláno ${ppl.length} lidem po ${fmt(a)} (celkem ${f0(tot)})`);render(1)},
 backup(){download(`nasebanka-zaloha-${today()}.json`,JSON.stringify({verze:1,datum:new Date().toISOString(),S,TEAM},null,1),'application/json');log('Stáhl zálohu dat');toast('Záloha stažena.')},
 pollNew(){modal('Nová anketa','<label class="field">Otázka<input id="plQ" maxlength="100" placeholder="Má být víc her?"></label><label class="field">Možnosti (oddělit čárkou)<input id="plO" placeholder="Ano, Ne, Je mi to jedno"></label>','Zveřejnit',()=>{const q=$('#plQ').value.trim(),o=$('#plO').value.split(',').map(x=>x.trim()).filter(Boolean);if(!q||o.length<2){toast('Otázka a aspoň 2 možnosti.',false);return false}S.polls.unshift({q,opts:o,votes:o.map(()=>0),mine:null,by:S.me,d:'Teď'});setTimeout(()=>render(1))})},
 vote(b){const[i,k]=b.dataset.v.split('|').map(Number),p=S.polls[i];if(p.mine!==null)p.votes[p.mine]--;if(p.mine===k)p.mine=null;else{p.mine=k;p.votes[k]++}render(1)},
 betOn(b){if(guard())return;const[j,k]=b.dataset.v.split('|').map(Number),bt=S.bets[j];modal('Vsadit · '+bt.opts[k],`<label class="field">Kolik žetonů (máš ${S.chips})<input id="btA" type="number" min="1" placeholder="10"></label>`,'Vsadit',()=>{const a=Math.floor(num('#btA'));if(!(a>0)||a>S.chips){toast('Neplatný počet žetonů.',false);return false}if(betPre(a)===false)return false;S.chips-=a;S.cas.lost+=a;bt.pool[k]+=a;bt.mine[k]=(bt.mine[k]||0)+a;toast(`Vsazeno ${a} ž. na ${bt.opts[k]}`);setTimeout(()=>render(1))})},
 betWin(b){const[j,k]=b.dataset.v.split('|').map(Number),bt=S.bets[j],tot=bt.pool.reduce((a,c)=>a+c,0);bt.open=false;bt.win=k;const my=bt.mine[k]||0;if(my){const w=Math.floor(my/bt.pool[k]*tot*.95);S.chips+=w;S.cas.won+=w;toast(`Vyhodnoceno: ${bt.opts[k]}. Vyhráváš ${w} ž.!`)}else toast('Vyhodnoceno: '+bt.opts[k]);log('Vyhodnotil sázku · '+bt.q+' → '+bt.opts[k]);render(1)},
 betNew(){modal('Nová sázka',`<label class="field">Událost<input id="bnQ" maxlength="100" placeholder="Kdo vyhraje turnaj?"></label><label class="field">Možnosti (čárkou)<input id="bnO" placeholder="9.A, 9.B, 8.A"></label>`,'Vypsat',()=>{const q=$('#bnQ').value.trim(),o=$('#bnO').value.split(',').map(x=>x.trim()).filter(Boolean);if(!q||o.length<2){toast('Událost a aspoň 2 možnosti.',false);return false}S.bets.unshift({q,opts:o,pool:o.map(()=>0),mine:{},open:true,by:S.me});setTimeout(()=>render(1))})},
 firmNew(){modal('Založit firmu',`<label class="field">Název firmy<input id="fnN" maxlength="30" placeholder="Moje Firma"></label><div class="cols2"><label class="field">Zkratka (3–5 písmen)<input id="fnId" maxlength="5" placeholder="MOJE" style="text-transform:uppercase"></label><label class="field">Počet akcií<input id="fnSh" type="number" min="100" value="1000"></label></div><label class="field">Startovní cena akcie (Sh)<input id="fnP" type="number" min="1" value="5"></label><p class="mute sm">Žádost schválí majitel, Banka, vývojář nebo zástupce.</p>`,'Poslat žádost',()=>{const n=$('#fnN').value.trim(),id=$('#fnId').value.trim().toUpperCase(),sh=Math.floor(num('#fnSh')),p=num('#fnP');if(!n||!/^[A-Z]{3,5}$/.test(id)||!(sh>=100)||!(p>0)){toast('Vyplň všechno správně.',false);return false}if(S.firms.some(f=>f.id===id)||S.firmReqs.some(f=>f.id===id)){toast('Zkratka je obsazená.',false);return false}S.firmReqs.push({n,id,owner:S.me,base:p,shares:sh,d:'Teď'});toast('Žádost o firmu odeslána.')})},
 firmOk(b){const r=S.firmReqs.splice(+b.dataset.v,1)[0];const f={id:r.id,n:r.n,owner:r.owner,base:r.base,shares:r.shares,sold:0,h:[]};f.h=[fprice(f),fprice(f)];S.firms.push(f);log('Schválil firmu · '+r.n);toast('Firma '+r.n+' je na burze!');render(1)},
 firmNo(b){const r=S.firmReqs.splice(+b.dataset.v,1)[0];log('Zamítl firmu · '+r.n);toast('Žádost zamítnuta.',false);render(1)},
 fBuy(b){if(guard())return;const f=S.firms.find(x=>x.id===b.dataset.v);modal('Koupit · '+f.n,`<label class="field">Počet akcií (cena teď ${fmt(fprice(f))})<input id="fq" type="number" min="1" value="10"></label>`,'Koupit',()=>{const q=Math.floor(num('#fq'));if(!(q>0)||q>f.shares-f.sold){toast('Tolik akcií není.',false);return false}const c=+(q*fprice(f)).toFixed(2);if(c>S.bal){toast('Nemáš dost Sh.',false);return false}S.bal-=c;const fee=c*S.cfg.fee/100;fund(fee,'Poplatek · '+f.id);f.acct=(f.acct||0)+c-fee;(f.tx=f.tx||[]).unshift({t:'Prodej akcií · '+S.me,a:c-fee,d:'Teď'});f.sold+=q;S.fhold[f.id]=(S.fhold[f.id]||0)+q;f.h.push(fprice(f));addTx('inv','Nákup · '+f.n,'firma spolužáka',-c);toast(`Koupeno ${q} akcií ${f.n}`);setTimeout(()=>render(1))})},
 fSell(b){if(guard())return;const f=S.firms.find(x=>x.id===b.dataset.v),o=S.fhold[f.id]||0;if(!o)return toast('Nemáš žádné akcie této firmy.',false);const g=+(o*fprice(f)*(1-S.cfg.fee/100)).toFixed(2);modal('Prodat · '+f.n,`<p class="sm">Prodáš všech ${o} akcií za ${fmt(g)} (zpět firmě).</p>`,'Prodat',()=>{if((f.acct||0)<g){toast('Firma teď nemá dost peněz na odkup akcií.',false);return false}f.acct-=g;(f.tx=f.tx||[]).unshift({t:'Odkup akcií · '+S.me,a:-g,d:'Teď'});S.bal+=g;fund(o*fprice(f)-g,'Poplatek · '+f.id);f.sold-=o;S.fhold[f.id]=0;f.h.push(fprice(f));addTx('inv','Prodej · '+f.n,'firma spolužáka',g);toast('Prodáno.');setTimeout(()=>render(1))})},
 colBuy(b){if(guard())return;const id=b.dataset.v,c=COL[id];if(c.price>S.bal)return toast('Nemáš dost Sh.',false);S.bal-=c.price;c.left--;fund(c.price,'Sběratelská karta · '+c.n);ownCol(id);addTx('inv','Sběratelská karta',c.n,-c.price);toast(`Máš kartu ${c.n}! Najdeš ji i v Nastavení → Moje karta.`);render(1)},
 listBuy(b){if(guard())return;const i=+b.dataset.v,l=S.listings[i],c=COL[l.col];if(l.price>S.bal)return toast('Nemáš dost Sh.',false);if(S.mycol.includes(l.col))return toast('Tuhle kartu už máš.',false);S.bal-=l.price;fund(l.price*S.cfg.fee/100,'Poplatek · karta');S.listings.splice(i,1);ownCol(l.col);addTx('inv','Karta od '+l.seller,c.n,-l.price);toast(`Koupeno od ${l.seller}: ${c.n}`);render(1)},
 listNew(){modal('Prodat kartu',`<label class="field">Karta<select id="lsC">${S.mycol.filter(id=>!S.listings.some(l=>l.col===id&&l.seller===S.me)).map(id=>`<option value="${id}">${COL[id].n}</option>`).join('')}</select></label><label class="field">Cena (Sh)<input id="lsP" type="number" min="1" placeholder="200"></label>`,'Nabídnout',()=>{const id=$('#lsC').value,p=num('#lsP');if(!id||!(p>0)){toast('Vyber kartu a cenu.',false);return false}S.listings.unshift({col:id,seller:S.me,price:p});toast('Karta je v nabídce.');setTimeout(()=>render(1))})},
 listDel(b){S.listings.splice(+b.dataset.v,1);render(1)},
 avPick(b){const[e,g]=b.dataset.v.split('|');S.avatar[S.me]={e,g:+g};toast('Profilový obrázek změněn.');render(1)},
 avReset(){delete S.avatar[S.me];render(1)},
 nickSave(){const v=$('#nickIn').value.trim().toLowerCase().replace(/^@/,'');if(!/^[a-z0-9_.]{3,16}$/.test(v))return toast('Přezdívka: 3–16 znaků, malá písmena a čísla.',false);if(Object.entries(S.nick).some(([n,k])=>k===v&&n!==S.me))return toast('@'+v+' už někdo má.',false);S.nick[S.me]=v;toast('Přezdívka @'+v+' uložena.');render(1)},
 lang(b){S.lang=b.dataset.v;document.documentElement.lang=S.lang;toast(S.lang==='en'?'Language: English (prototype – main texts)':'Jazyk: čeština');render(1)},
 async pushTest(){await sysNotify('NašeBanka','Zkušební notifikace funguje 🎉');toast('Notifikace odeslána.')},
 logoutAll(){S.logins=S.logins.filter(l=>l.cur);log('Odhlásil všechna ostatní zařízení');toast('Odhlášeno ze všech ostatních zařízení.');render(1)},
 async pkOn(){if(!window.PublicKeyCredential)return toast('Tenhle prohlížeč otisk prstu nepodporuje.',false);try{const uid=crypto.getRandomValues(new Uint8Array(16));const c=await navigator.credentials.create({publicKey:{challenge:crypto.getRandomValues(new Uint8Array(32)),rp:{name:'NašeBanka'},user:{id:uid,name:S.me,displayName:S.me},pubKeyCredParams:[{type:'public-key',alg:-7},{type:'public-key',alg:-257}],authenticatorSelection:{userVerification:'required',residentKey:'preferred'},timeout:60000}});S.passkey={id:b64(c.rawId),user:S.me};try{localStorage.setItem('nb-passkey',JSON.stringify(S.passkey))}catch(e){}toast('Přihlášení otiskem je zapnuté.');render(1)}catch(e){toast(e.name==='NotAllowedError'?'Zrušeno nebo zařízení nemá zámek obrazovky.':e.name==='SecurityError'||e.name==='NotSupportedError'?'Tady otisk nejde – otevři prototyp na celou obrazovku.':'Nepovedlo se: '+e.name,false)}},
 pkOff(){S.passkey=null;try{localStorage.removeItem('nb-passkey')}catch(e){}toast('Přihlášení otiskem vypnuto.');render(1)},
 async pkLogin(){const pk=S.passkey;if(!pk)return toast('Otisk prstu zatím nemáš zapnutý.',false);try{await navigator.credentials.get({publicKey:{challenge:crypto.getRandomValues(new Uint8Array(32)),allowCredentials:[{type:'public-key',id:unb64(pk.id)}],userVerification:'required',timeout:60000}});const p=TEAM.find(x=>x.n===pk.user);S.me=p.n;S.role=p.k;$('#login').classList.remove('open');addLogin('otisk prstu');location.hash=p.k==='bank'?'#/banka':'#/ucet';render();toast('Přihlášeno otiskem prstu.')}catch(e){toast('Přihlášení otiskem se nepovedlo.',false)}},
});
function addLogin(how){S.logins.forEach(l=>l.cur=false);const ua=navigator.userAgent,dev=/iPhone/.test(ua)?'iPhone · Safari':/Android/.test(ua)?'Android · Chrome':/Windows/.test(ua)?'Windows · '+(/Edg/.test(ua)?'Edge':'Chrome'):'Počítač';S.logins.unshift({d:'Dnes '+nowT(),dev:dev+(how?' · '+how:''),cur:true})}
document.addEventListener('change',async e=>{const t=e.target;
 if(t.id==='pWhen')$('#pDateW').style.display=t.value==='later'?'':'none';
 if(t.id==='bigOn'){S.big=t.checked;document.documentElement.classList.toggle('big',S.big)}
 if(t.id==='hcOn'){S.hc=t.checked;document.documentElement.classList.toggle('hc',S.hc)}
 if(t.id==='pushOn'){if(t.checked){if(!('Notification' in window))return toast('Prohlížeč notifikace neumí.',false);const p=await Notification.requestPermission();S.phoneNotif=p==='granted';toast(S.phoneNotif?'Notifikace zapnuté.':'Notifikace jsi v prohlížeči nepovolil.',S.phoneNotif)}else S.phoneNotif=false;render(1)}
 if(t.id==='avFile'&&t.files[0]){const img=new Image();img.onload=()=>{const c=document.createElement('canvas');c.width=c.height=128;const x=c.getContext('2d'),m=Math.min(img.width,img.height);x.drawImage(img,(img.width-m)/2,(img.height-m)/2,m,m,0,0,128,128);S.avatar[S.me]={img:c.toDataURL('image/jpeg',.85)};toast('Fotka nastavená.');render(1)};img.src=URL.createObjectURL(t.files[0])}
 if(t.id==='restore'&&t.files[0]){try{const d=JSON.parse(await t.files[0].text());if(!d.S||!d.TEAM)throw 0;Object.assign(S,d.S);TEAM.splice(0,TEAM.length,...d.TEAM);log('Obnovil banku ze zálohy');toast('Banka obnovena ze zálohy.');render(1)}catch(err){toast('Tohle není platná záloha.',false)}}
});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='chatIn'){e.preventDefault();A.chatSend()}});
setInterval(()=>{const el=$('#undoLeft');if(el&&S.undo){const m=Math.ceil((S.undo.until-Date.now())/60000);if(m<=0)render(1);else el.textContent=m}},15000);
{const lm=loginMode;loginMode=function(reg){lm(reg);if(!reg&&S.passkey)$('#lgBody').insertAdjacentHTML('beforeend',`<button class="ghost" type="button" data-act="pkLogin" style="margin-top:10px">${I('finger')}Přihlásit otiskem prstu (${S.passkey.user})</button>`)}}
$('#loginForm').addEventListener('submit',()=>setTimeout(()=>{if(!$('#login').classList.contains('open'))addLogin()},50));
