function sampleImg(){const c=document.createElement('canvas');c.width=900;c.height=650;const x=c.getContext('2d');const g=x.createLinearGradient(0,0,0,650);g.addColorStop(0,'#7dd3fc');g.addColorStop(.6,'#fde68a');g.addColorStop(1,'#86efac');x.fillStyle=g;x.fillRect(0,0,900,650);
 x.fillStyle='#fef3c7';x.beginPath();x.arc(700,150,80,0,7);x.fill();x.fillStyle='#4ade80';x.beginPath();x.ellipse(250,640,420,170,0,0,7);x.fill();x.fillStyle='#22c55e';x.beginPath();x.ellipse(720,660,380,150,0,0,7);x.fill();
 x.fillStyle='#92400e';x.beginPath();x.ellipse(430,440,120,80,0,0,7);x.fill();x.beginPath();x.arc(560,360,62,0,7);x.fill();x.fillStyle='#78350f';x.beginPath();x.ellipse(600,320,22,40,.5,0,7);x.fill();x.beginPath();x.ellipse(522,320,22,40,-.5,0,7);x.fill();
 x.fillStyle='#111';x.beginPath();x.arc(545,350,7,0,7);x.arc(578,350,7,0,7);x.fill();x.beginPath();x.arc(562,378,10,0,7);x.fill();[340,380,470,510].forEach(px=>{x.fillStyle='#92400e';x.fillRect(px,480,22,70)});return c.toDataURL('image/jpeg',.85)}
