const PRESETS={none:['Bez filtru',{}],neon:['Neon',{sat:165,ct:118}],bw:['Černobílá',{sat:0,ct:118}],vintage:['Vintage',{sat:70,br:106,ct:88,hue:18}],warm:['Teplá',{hue:-14,sat:122,br:104}],cold:['Studená',{hue:24,sat:88}],moody:['Tmavá',{br:72,ct:112,sat:90}]};
const PATS={none:['Žádný',''],dots:['Tečky','radial-gradient(rgba(255,255,255,.22) 2px,transparent 2.6px) 0 0/18px 18px'],stripes:['Pruhy','repeating-linear-gradient(45deg,rgba(255,255,255,.09) 0 10px,transparent 10px 20px)'],grid:['Mřížka','linear-gradient(rgba(255,255,255,.1) 1px,transparent 1px) 0 0/22px 22px,linear-gradient(90deg,rgba(255,255,255,.1) 1px,transparent 1px) 0 0/22px 22px'],waves:['Vlny','radial-gradient(circle at 50% 120%,transparent 18px,rgba(255,255,255,.14) 19px,transparent 22px) 0 0/36px 24px'],glow:['Záře','radial-gradient(circle at 85% 15%,rgba(255,255,255,.45),transparent 40%)']};
const dzBg=()=>DZ.mode==='img'&&DZ.img?`url(${DZ.img}) center/cover`:[PATS[DZ.pat][1],`linear-gradient(${DZ.ang}deg,${DZ.c1},${DZ.c2})`].filter(Boolean).join(',');
const canEditDesign=c=>['own','bank','dev'].includes(S.role)||c.by===S.me;
function loadSrc(url,keep){return new Promise(res=>{const im=new Image();im.onload=()=>{const m=Math.max(im.width,im.height),k=Math.min(1,1600/m);let src=im;if(k<1){const c=document.createElement('canvas');c.width=im.width*k;c.height=im.height*k;c.getContext('2d').drawImage(im,0,0,c.width,c.height);src=c}DZ.srcImg=src;DZ.src=url;DZ.mode='img';if(!keep)Object.assign(DZ,ADJ);res()};im.src=url})}
function compose(){if(DZ.mode!=='img'||!DZ.srcImg)return;const c=document.createElement('canvas');c.width=640;c.height=404;const x=c.getContext('2d'),im=DZ.srcImg;
 x.fillStyle='#000';x.fillRect(0,0,640,404);x.filter=`brightness(${DZ.br}%) contrast(${DZ.ct}%) saturate(${DZ.sat}%) hue-rotate(${DZ.hue}deg) blur(${DZ.blur}px)`;
 x.save();x.translate(320+DZ.px*3.2,202+DZ.py*2.02);x.rotate(DZ.rot*Math.PI/180);if(DZ.flip)x.scale(-1,1);
 const rw=DZ.rot%180?im.height:im.width,rh=DZ.rot%180?im.width:im.height,s=Math.max(640/rw,404/rh)*DZ.zoom/100;x.drawImage(im,-im.width*s/2,-im.height*s/2,im.width*s,im.height*s);x.restore();x.filter='none';
 if(DZ.ov){x.fillStyle=`rgba(0,0,0,${DZ.ov/100})`;x.fillRect(0,0,640,404)}
 if(DZ.vig){const g=x.createRadialGradient(320,202,110,320,202,400);g.addColorStop(0,'rgba(0,0,0,0)');g.addColorStop(1,`rgba(0,0,0,${DZ.vig/100})`);x.fillStyle=g;x.fillRect(0,0,640,404)}
 DZ.lum=lumOf(x);DZ.img=c.toDataURL('image/jpeg',.88)}
function lumOf(x){let t=0,n=0;[[20,16,300,50],[20,330,600,60],[20,170,600,60]].forEach(([a,b,w,h])=>{const d=x.getImageData(a,b,w,h).data;for(let i=0;i<d.length;i+=32){t+=(.2126*d[i]+.7152*d[i+1]+.0722*d[i+2])/255;n++}});return t/n}
function gradLum(){const h=s=>{const v=parseInt(s.slice(1),16);return(.2126*(v>>16)+.7152*(v>>8&255)+.0722*(v&255))/255};return(h(DZ.c1)+h(DZ.c2))/2}
function readHtml(){const l=DZ.mode==='img'?(DZ.lum??.5):gradLum(),bad=DZ.dark?l<.42:l>.62;return `<div class="readok ${bad?'bad':'ok'}" id="dzRead">${bad?`⚠ Text bude špatně čitelný – ${DZ.dark?'použij světlý text':'zapni tmavý text nebo ztmav obrázek'}.`:'✓ Text na kartě je dobře čitelný.'} <button class="ghost sm" data-act="dzAuto" style="margin-left:6px">Nastavit automaticky</button></div>`}
let rafZ;function recompose(){cancelAnimationFrame(rafZ);rafZ=requestAnimationFrame(()=>{compose();dzPreview();const r=$('#dzRead');if(r)r.outerHTML=readHtml()})}
